- 				return -ENOMEM;
- 		}
- 	}
- 
- 	/* Use GRPH_PFLIP interrupt */
- 	for (i = VISLANDS30_IV_SRCID_D1_GRPH_PFLIP;
- 			i <= VISLANDS30_IV_SRCID_D6_GRPH_PFLIP; i += 2) {
- 		r = amdgpu_irq_add_id(adev, client_id, i, &adev->pageflip_irq);
