- void amdgpu_dm_update_backlight_caps(struct amdgpu_display_manager *dm,
- 				     int bl_idx)
- {
- 	struct amdgpu_dm_backlight_caps *caps = &dm->backlight_caps[bl_idx];
- 
- 	if (caps->caps_valid)
