- 	}
- #else
- 	if (caps->aux_support)
- 		return;
- 
- 	caps->min_input_signal = AMDGPU_DM_DEFAULT_MIN_BACKLIGHT;
- 	caps->max_input_signal = AMDGPU_DM_DEFAULT_MAX_BACKLIGHT;
